      alice_victoria_benson_bischel_1902:{name:"Alice Victoria Benson Bischel",slug:"alice-victoria-benson-bischel",aliases:["Alice Bensen","Alice Beschel"],relation:"Dotter till Nils Johan",born:"1902-11-27",died:"1987-03",location:"Chicago / Evanston, Illinois",status:"strong",summary:"Alice växte upp i Benson-hushållet i Chicago och blev utgångspunkt för en tekniskt och akademiskt präglad Bischel-gren.",story:["Alice föddes enligt stark index- och sekundäruppgift den 27 november 1902 i Chicago. Original födelseattest återstår.","Hon gifte sig med Albert Clair Bischel den 15 september 1926 i Cook County. Paret fick barnen Dwight William och Elinor Liane.","Det svenska arvskiftet 1955 namnger henne som Mrs Alice Beschel på 1569 Florence i Evanston och bekräftar att hon var Nils Johans dotter."],facts:[["Föräldrar","John Benson och Ida Johnson"],["Make","Albert Clair Bischel"],["Vigsel","1926-09-15, Cook County"],["Barn","Dwight William och Elinor Liane Bischel"],["Adress 1955","1569 Florence, Evanston, Illinois"]],timeline:[["1902-11-27","Föds enligt stark index-/sekundäruppgift."],["1926-09-15","Gifter sig med Albert Clair Bischel."],["1955-01-12","Namnges i det svenska arvskiftet."],["1987-03","Avlider i Evanston enligt sekundärt registerspår."]],sources:["1920 U.S. Federal Census.","Arvskifte efter Alma Josefina Bengtsson 1955.","FamilySearch-index för Alice och Albert.","AncientFaces, sekundärt dödsregisterspår."],uncertainties:["Original födelseattest och original dödsattest/obituary återstår."]},
