      wesley_tk_bischel:{name:"Wesley T. K. Bischel",slug:"wesley-tk-bischel",aliases:["Wesley T.K. Bischel"],relation:"Barnbarnsbarn till Nils Johan",location:"Lancaster, Pennsylvania",status:"confirmed",isLiving:true,summary:"Tekniskt verksam inom produktutveckling och uppfinnararbete för Armstrong World Industries.",story:["Patentregister visar ett långvarigt arbete med byggsystem, undertak, övergångselement och dekorativa tekniska taklösningar för Armstrong World Industries.","Källorna ger inte en formell jobbtitel, så han beskrivs försiktigt som tekniskt verksam inom produktutveckling och uppfinnararbete."],facts:[["Föräldrar","Dwight William och Sally Krauss Bischel"],["Maka","Marsha Stalker Bischel"],["Barn","Samuel Bischel"],["Verksamhet","Armstrong World Industries; patent inom arkitektoniska byggsystem"],["Patentexempel","U.S. Patent 5,265,393, Decorative Elements for Subceilings"]],sources:["Dwight William Bischels obituary.","Google Patents, US5265393A.","European Patent Office, EP0884428NWA2."],uncertainties:["Formell jobbtitel framgår inte av patentkällorna."]},
      marsha_stalker_bischel:{name:"Marsha Stalker Bischel",slug:"marsha-stalker-bischel",relation:"Maka till Wesley",location:"Lancaster, Pennsylvania",status:"confirmed",isLiving:true,summary:"Materialforskare med doktorsexamen och lång verksamhet vid Armstrong World Industries.",story:["Marsha studerade vid University of Delaware, tog en masterexamen i materials science vid University of Connecticut och återvände senare till Delaware för en Ph.D. i materials science.","Från 2000 arbetade hon som Senior Research Scientist vid Armstrong World Industries med material för invändiga byggnadsytor."],facts:[["Make","Wesley T. K. Bischel"],["Barn","Samuel Bischel"],["Utbildning","University of Delaware; University of Connecticut; Ph.D. i materials science"],["Yrke","Senior Research Scientist, Armstrong World Industries från 2000"]],sources:["University of Delaware, Chemical & Biomolecular Engineering Magazine 2017.","Shirley Ann Stalkers obituary."]},
