      edna_benson_weltner_1905:{name:"Edna Benson Weltner",slug:"edna-benson-weltner",relation:"Dotter till Nils Johan",born:"ca 1905–1906",location:"Chicago / Mission, Kansas",status:"confirmed",summary:"Edna växte upp i Chicago och etablerade sig senare med Adolph Weltner i Kansas Citys finans- och affärsmiljö.",story:["1920 års census visar Edna som 14-årig dotter i John och Ida Bensons hushåll i Chicago.","Adolph Weltner flyttade från Chicago till Kansas City 1927. Eftersom sonen Edward föddes där 1928 är det starkt sannolikt att Edna följde med omkring 1927.","Efter Adolphs död 1959 övergick hans aktier i A.E. Weltner & Co. till Edna. Federal Register anger samtidigt att hon inte själv hade varit aktiv i bolagens verksamhet."],facts:[["Föräldrar","John Benson och Ida Johnson"],["Make","Adolph E. Weltner"],["Barn","Edward B. Weltner"],["Adress 1955","4100 Brookridge, Mission, Kansas"],["Företagsintresse 1959","Ärvde Adolphs aktier men hade inte haft operativ roll"]],timeline:[["ca 1905–1906","Föds i Illinois enligt 1920 census."],["ca 1927","Flytt till Kansas City med Adolph är starkt stödd men inte slutligt primärbelagd."],["1955-01-12","Namnges i det svenska arvskiftet."],["1959","Ärver Adolphs aktier enligt Federal Register."]],sources:["1920 U.S. Federal Census.","Arvskifte efter Alma Josefina Bengtsson 1955.","Edward B. Weltners obituary.","Federal Register, 1959-06-20."],uncertainties:["Exakt födelse- och dödsdatum samt vigseldatum saknas."]},
      adolph_e_weltner:{name:"Adolph E. Weltner",slug:"adolph-e-weltner",relation:"Make till Edna",died:"1959-02-23",location:"Chicago / Kansas City",status:"confirmed",summary:"Investmentrådgivare och företagsgrundare i Kansas City.",story:["Adolph flyttade från Chicago till Kansas City 1927 och grundade A.E. Weltner & Co. samt Security Management, Inc., där han var president.","Han hade framträdande roller inom investmentbankbranschen och utsågs 1934 till en regional branschkommitté."],facts:[["Maka","Edna Benson Weltner"],["Barn","Edward B. Weltner"],["Företag","A.E. Weltner & Co. och Security Management, Inc."],["Yrke","Investment counselor och securities dealer"]],sources:["FRASER, Monthly Bank News, mars 1959.","Federal Register, 1959-06-20.","SEC Historical Society, Investment Bankers Code Committee minutes 1934."]},
      edward_b_weltner_1928:{name:"Edward B. Weltner",slug:"edward-b-weltner",relation:"Barnbarn till Nils Johan",born:"1928-09-10",died:"2019-03-19",location:"Kansas City, Missouri / Kansas",status:"confirmed",summary:"Finansman, företagare, pilot, dykare och aktiv deltagare i Kansas City-områdets förenings- och samhällsliv.",story:["Edward växte upp i Kansas City, blev Eagle Scout och tog BA 1950 samt MBA in Finance 1952 vid University of Kansas.","Han började arbeta med sin far i A.E. Weltner & Co. och Security Management. Efter faderns död blev han ägare och president för Security Management och fortsatte senare som ledande mäklare och finansanalytiker.","Edward ägde också Witte Engine Corp., Regal Aluminum Products och Kansas City Central Paper Box Co. Han hade uppdrag i klubbar, parkstyrelse och planeringskommission.","Han och hustrun Sue besökte alla 50 amerikanska delstater och 32 länder. Edward hade både privatflygcertifikat och scubadykarcertifikat."],facts:[["Föräldrar","Adolph E. Weltner och Edna Benson Weltner"],["Utbildning","BA 1950 och MBA in Finance 1952, University of Kansas"],["Yrke","Finans, värdepapper och företagande"],["Maka","Sue E. Gibson Weltner; gifta 1954"],["Barn","Russell, Douglas och Steven Weltner"],["Föreningsliv","Kansas City Society of Financial Analysts, Mission Hills Country Club med flera"]],timeline:[["1928-09-10","Föds i Kansas City, Missouri."],["1952","Tar MBA och börjar arbeta med sin far."],["1954","Gifter sig med Sue E. Gibson."],["1959","Blir ägare och president för Security Management efter faderns död."],["1972","Väljs till president för Kansas City Society of Financial Analysts."],["2019-03-19","Avlider."]],sources:["Edward B. Weltner obituary, Muehlebach Funeral Care / Kansas City Star.","Johnson County Kansas, Former Commissioners.","Prairie Village historik."]},
