      carl_richard_sholeen_1928:{name:"Carl Richard Sholeen",slug:"carl-richard-sholeen",relation:"Barnbarn till Nils Johan",born:"1928-03-28",died:"2017-07-13",location:"Chicago / Glenwood, Illinois",status:"confirmed",summary:"Marinveteran, fastighetsvärderare och föreningsaktiv geograf med mer än fyrtio års yrkesliv.",story:["Carl och Lucille träffades vid en ungdomssamling 1947 och gifte sig 1949. Han tjänstgjorde vid Great Lakes Naval Center 1950–1951 under Koreakonflikten.","Han började inom fastighetsförsäljning och gjorde därefter mer än fyrtio års karriär som appraiser, till sist chief appraiser för LaSalle/Talman Bank i Chicago.","Han var president för Chicago Chapter of the Society of Real Estate Appraisers 1989 och även president för Geographic Society of Chicago."],facts:[["Föräldrar","Carl Sigurd och Esther Sholeen"],["Militärtjänst","U.S. Navy, YNT3, Koreakrigsperioden"],["Maka","Lucille Erdmann Sholeen"],["Vigsel","1949-10-01"],["Barn","Jeffery Paul och Todd Carl Sholeen"],["Yrke","Fastighetsvärderare och chief appraiser"]],timeline:[["1928-03-28","Föds."],["1949-10-01","Gifter sig med Lucille Erdmann."],["1950–1951","Tjänstgör vid Great Lakes Naval Center."],["1964","Familjen flyttar till Glenwood."],["1989","President för Chicago Chapter of the Society of Real Estate Appraisers."],["1995","Pensioneras från banken men fortsätter med kommersiell värdering."],["2017-07-13","Avlider."]],sources:["Lucille Erdmann Sholeen, Reinbolt Family, Henry County Historical Society 2008.","Abraham Lincoln National Cemetery/veteranregister."]},
