      jeffery_paul_sholeen_1952:{name:"Jeffery Paul Sholeen",slug:"jeffery-paul-sholeen",aliases:["Jeff Sholeen"],relation:"Barnbarnsbarn till Nils Johan",born:"1952-10-11",location:"New York City",status:"confirmed",isLiving:true,summary:"Fastighetsmäklare i New York med lång karriär hos Corcoran Group.",story:["Jeff är Chicago-född och bosatt i New York sedan 1977. Han har arbetat vid Corcoran Group sedan 1992 och presenteras som Senior Vice President, flerårig Top 25-producent och föredragshållare i mäklarutbildningar."],facts:[["Föräldrar","Carl Richard och Lucille Sholeen"],["Yrke","Senior Vice President, Corcoran Group"],["New York","Bosatt där sedan 1977"]],sources:["Lucille Erdmann Sholeens familjehistoria 2008.","StreetEasy/Corcoran offentlig professionell biografi."],uncertainties:["Några säkert belagda barn har inte identifierats."]},
